import os,sys,json,re,sqlite3,secrets,hashlib,base64,struct,threading,time,datetime,urllib.parse,cgi,socket
from http.server import ThreadingHTTPServer,BaseHTTPRequestHandler
DB='/app/huddle.db'; PORT=int(sys.argv[1]) if len(sys.argv)>1 else 8000; NODE=PORT-8000
lock=threading.RLock(); clients=[]; irc_clients=[]
def db():
 c=sqlite3.connect(DB,timeout=20); c.row_factory=sqlite3.Row; return c
def init():
 with db() as c:
  c.executescript('''CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,password TEXT,display_name TEXT,timezone TEXT,avatar_url TEXT,status_text TEXT,status_emoji TEXT);
CREATE TABLE IF NOT EXISTS tokens(token TEXT PRIMARY KEY,user_id INTEGER);
CREATE TABLE IF NOT EXISTS workspaces(id INTEGER PRIMARY KEY,slug TEXT UNIQUE,name TEXT,owner_id INTEGER,join_mode TEXT);
CREATE TABLE IF NOT EXISTS members(workspace_id INTEGER,user_id INTEGER,role TEXT,PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY,workspace_id INTEGER,name TEXT,is_private INTEGER,is_dm INTEGER DEFAULT 0,topic TEXT DEFAULT '',is_archived INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS cmembers(channel_id INTEGER,user_id INTEGER,PRIMARY KEY(channel_id,user_id));
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,channel_id INTEGER,author_id INTEGER,body TEXT,parent_id INTEGER,created_at TEXT,edited_at TEXT,deleted INTEGER DEFAULT 0,event_id INTEGER);
CREATE TABLE IF NOT EXISTS reactions(message_id INTEGER,user_id INTEGER,emoji TEXT,PRIMARY KEY(message_id,user_id,emoji));
CREATE TABLE IF NOT EXISTS pins(message_id INTEGER PRIMARY KEY,user_id INTEGER,pinned_at TEXT);
CREATE TABLE IF NOT EXISTS files(id INTEGER PRIMARY KEY,uploader_id INTEGER,filename TEXT,content_type TEXT,size INTEGER,data BLOB,created_at TEXT,attached INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS groups_(id INTEGER PRIMARY KEY,workspace_id INTEGER,handle TEXT,name TEXT,creator_id INTEGER,user_ids TEXT,UNIQUE(workspace_id,handle));
CREATE TABLE IF NOT EXISTS invites(code TEXT PRIMARY KEY,workspace_id INTEGER,invited_user_id INTEGER,max_uses INTEGER,uses INTEGER DEFAULT 0,expires INTEGER);
CREATE TABLE IF NOT EXISTS reads(user_id INTEGER,channel_id INTEGER,last_read INTEGER,PRIMARY KEY(user_id,channel_id));
CREATE TABLE IF NOT EXISTS seq(channel_id INTEGER PRIMARY KEY,n INTEGER)''')
def now(): return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec='milliseconds').replace('+00:00','Z')
def objuser(r):
 return {k:r[k] for k in ('id','username','display_name','timezone','avatar_url','status_text','status_emoji')}
def tokuser(t):
 with db() as c:
  r=c.execute('SELECT u.* FROM users u JOIN tokens t ON t.user_id=u.id WHERE t.token=?',(t,)).fetchone()
 return r
def js(o): return json.dumps(o,separators=(',',':')).encode()
def msgobj(c,r):
 u=c.execute('SELECT * FROM users WHERE id=?',(r['author_id'],)).fetchone()
 rr=c.execute('SELECT emoji,COUNT(*) n,GROUP_CONCAT(user_id) ids FROM reactions WHERE message_id=? GROUP BY emoji',(r['id'],)).fetchall()
 fs=[]
 return {'id':r['id'],'channel_id':r['channel_id'],'author_id':r['author_id'],'author':objuser(u),'body':r['body'],'parent_id':r['parent_id'],'reply_count':c.execute('SELECT COUNT(*) FROM messages WHERE parent_id=? AND deleted=0',(r['id'],)).fetchone()[0],'created_at':r['created_at'],'edited_at':r['edited_at'],'files':fs,'reactions':[{'emoji':x['emoji'],'count':x['n'],'user_ids':[int(z) for z in x['ids'].split(',')]} for x in rr],'mentions':[]}
def broadcast(ev,ch=None):
 raw=json.dumps(ev).encode()
 for s in list(clients):
  try:
   if ch is None or s[1] is None or s[1]==ch: ws_send(s[0],raw)
  except: clients.remove(s)
 for s in list(irc_clients):
  try:
   if ch and s[1]==ch and ev.get('type') in ('message.created','message.reply'):
    m=ev.get('message',{}); s[0].sendall(irc_line(':web!web@localhost PRIVMSG '+s[2]+' :'+m.get('body','')))
  except: pass
def ws_send(sock,data):
 b=data if isinstance(data,bytes) else data.encode(); h=bytes([0x81])
 if len(b)<126: h+=bytes([len(b)])
 elif len(b)<65536:h+=b'\x7e'+struct.pack('>H',len(b))
 else:h+=b'\x7f'+struct.pack('>Q',len(b))
 sock.sendall(h+b)
def err(h,n,text): h.send_response(n); h.send_header('Content-Type','application/json'); h.end_headers(); h.wfile.write(js({'error':text}))
class H(BaseHTTPRequestHandler):
 protocol_version='HTTP/1.1'
 def log_message(self,*a): pass
 def body(self):
  n=int(self.headers.get('Content-Length','0')); return json.loads(self.rfile.read(n) or b'{}')
 def auth(self):
  x=self.headers.get('Authorization',''); return tokuser(x[7:] if x.startswith('Bearer ') else '')
 def out(self,n,o):
  b=js(o); self.send_response(n); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(b))); self.end_headers(); self.wfile.write(b)
 def do_GET(self):
  p=urllib.parse.urlparse(self.path); path=p.path; q=urllib.parse.parse_qs(p.query)
  if path=='/api/health': return self.out(200,{'status':'ok','node_id':NODE})
  if path=='/': return self.page()
  if path=='/api/ws': return self.websocket(q.get('token',[''])[0])
  u=self.auth()
  if not u:return err(self,401,'authentication required')
  with db() as c:
   m=re.fullmatch(r'/api/users/(\d+)',path)
   if m:
    r=c.execute('SELECT * FROM users WHERE id=?',(m.group(1),)).fetchone()
    return self.out(200,{'user':objuser(r)}) if r else err(self,404,'not found')
   if path=='/api/auth/me': return self.out(200,{'user':objuser(u)})
   if path=='/api/workspaces':
    rows=c.execute('SELECT w.* FROM workspaces w JOIN members m ON m.workspace_id=w.id WHERE m.user_id=?',(u['id'],)).fetchall()
    return self.out(200,{'workspaces':[dict(x) for x in rows]})
   m=re.fullmatch(r'/api/workspaces/([^/]+)',path)
   if m:
    w=c.execute('SELECT * FROM workspaces WHERE slug=?',(m.group(1),)).fetchone()
    if not w:return err(self,404,'not found')
    cs=c.execute('SELECT * FROM channels WHERE workspace_id=? AND is_archived=0',(w['id'],)).fetchall()
    return self.out(200,{'workspace':dict(w),'channels':[dict(x) for x in cs],'read_state':{}})
   m=re.fullmatch(r'/api/workspaces/([^/]+)/members',path)
   if m:
    w=c.execute('SELECT * FROM workspaces WHERE slug=?',(m.group(1),)).fetchone()
    if not w:return err(self,404,'not found')
    rows=c.execute('SELECT m.*,u.username,u.display_name FROM members m JOIN users u ON u.id=m.user_id WHERE workspace_id=?',(w['id'],)).fetchall()
    return self.out(200,{'members':[dict(x) for x in rows]})
   m=re.fullmatch(r'/api/channels/(\d+)/members',path)
   if m:
    rows=c.execute('SELECT u.* FROM users u JOIN cmembers m ON m.user_id=u.id WHERE m.channel_id=?',(m.group(1),)).fetchall()
    return self.out(200,{'members':[objuser(x) for x in rows]})
   m=re.fullmatch(r'/api/channels/(\d+)/messages',path)
   if m:
    rows=c.execute('SELECT * FROM messages WHERE channel_id=? AND deleted=0 AND parent_id IS NULL ORDER BY id DESC LIMIT 200',(m.group(1),)).fetchall()
    return self.out(200,{'messages':[msgobj(c,x) for x in rows],'next_cursor':None})
   m=re.fullmatch(r'/api/messages/(\d+)/replies',path)
   if m:
    rows=c.execute('SELECT * FROM messages WHERE parent_id=? AND deleted=0 ORDER BY id',(m.group(1),)).fetchall()
    return self.out(200,{'replies':[msgobj(c,x) for x in rows],'next_cursor':None})
   m=re.fullmatch(r'/api/channels/(\d+)/pins',path)
   if m:
    rows=c.execute('SELECT p.*,m.* FROM pins p JOIN messages m ON m.id=p.message_id WHERE m.channel_id=? ORDER BY p.message_id DESC',(m.group(1),)).fetchall()
    return self.out(200,{'pins':[{'message':msgobj(c,x),'pinned_by':x['user_id'],'pinned_at':x['pinned_at']} for x in rows],'next_cursor':None})
   m=re.fullmatch(r'/api/channels/(\d+)/read',path)
   if m:
    r=c.execute('SELECT last_read FROM reads WHERE user_id=? AND channel_id=?',(u['id'],m.group(1))).fetchone(); lr=r['last_read'] if r else 0
    return self.out(200,{'read_state':{'channel_id':int(m.group(1)),'last_read_event_id':lr,'unread_count':0,'mention_count':0}})
   m=re.fullmatch(r'/api/files/(\d+)',path)
   if m:
    r=c.execute('SELECT id,uploader_id,filename,content_type,size,created_at FROM files WHERE id=?',(m.group(1),)).fetchone()
    return self.out(200,{'file':dict(r)}) if r else err(self,404,'not found')
   m=re.fullmatch(r'/api/files/(\d+)/download',path)
   if m:
    r=c.execute('SELECT * FROM files WHERE id=?',(m.group(1),)).fetchone()
    if not r:return err(self,404,'not found')
    self.send_response(200); self.send_header('Content-Type',r['content_type']); self.send_header('Content-Disposition','attachment; filename="'+r['filename']+'"'); self.send_header('Content-Length',str(r['size'])); self.end_headers(); self.wfile.write(r['data']); return
   if path=='/api/search':
    term=q.get('q',[''])[0]; rows=c.execute("SELECT * FROM messages WHERE deleted=0 AND body LIKE ? ORDER BY id DESC",(f'%{term}%',)).fetchall()
    return self.out(200,{'results':[msgobj(c,x) for x in rows],'next_cursor':None})
  err(self,404,'not found')
 def do_POST(self):
  p=urllib.parse.urlparse(self.path).path; u=self.auth()
  if p=='/api/auth/register':
   try:
    d=self.body(); un=d['username']; pw=d['password']
    if not re.fullmatch(r'[A-Za-z0-9_]+',un) or len(pw)<8:return err(self,400,'invalid')
    with db() as c:
     c.execute('INSERT INTO users(username,password,display_name,timezone,avatar_url,status_text,status_emoji) VALUES(?,?,?,?,?,?,?)',(un,pw,d.get('display_name',un),'UTC','','',''))
     uid=c.lastrowid; t=secrets.token_urlsafe(24); c.execute('INSERT INTO tokens VALUES(?,?)',(t,uid)); r=c.execute('SELECT * FROM users WHERE id=?',(uid,)).fetchone()
    return self.out(201,{'user':objuser(r),'token':t})
   except sqlite3.IntegrityError:return err(self,409,'duplicate')
   except:return err(self,400,'invalid')
  if p=='/api/auth/login':
   d=self.body()
   with db() as c:r=c.execute('SELECT * FROM users WHERE username=? AND password=?',(d.get('username'),d.get('password'))).fetchone()
   if not r:return err(self,401,'invalid credentials')
   t=secrets.token_urlsafe(24)
   with db() as c:c.execute('INSERT INTO tokens VALUES(?,?)',(t,r['id']))
   return self.out(200,{'user':objuser(r),'token':t})
  if not u:return err(self,401,'authentication required')
  d=self.body()
  with db() as c:
   m=re.fullmatch(r'/api/workspaces/([^/]+)/channels',p)
   if m:
    w=c.execute('SELECT * FROM workspaces WHERE slug=?',(m.group(1),)).fetchone()
    if not w:return err(self,404,'not found')
    if not re.fullmatch(r'[a-z0-9-]{1,32}',d.get('name','')):return err(self,400,'invalid name')
    try:
     c.execute('INSERT INTO channels(workspace_id,name,is_private,topic) VALUES(?,?,?,?)',(w['id'],d['name'],int(bool(d.get('is_private'))),d.get('topic',''))); r=c.execute('SELECT * FROM channels WHERE id=?',(c.lastrowid,)).fetchone(); c.execute('INSERT INTO cmembers VALUES(?,?)',(r['id'],u['id'])); return self.out(201,{'channel':dict(r)})
    except sqlite3.IntegrityError:return err(self,409,'duplicate')
   m=re.fullmatch(r'/api/channels/(\d+)/join',p)
   if m:
    ch=c.execute('SELECT * FROM channels WHERE id=?',(m.group(1),)).fetchone()
    if not ch:return err(self,404,'not found')
    c.execute('INSERT OR IGNORE INTO cmembers VALUES(?,?)',(ch['id'],u['id'])); c.execute('INSERT OR IGNORE INTO members VALUES(?,?,?)',(ch['workspace_id'],u['id'],'member')); return self.out(200,{'channel':dict(ch)})
   m=re.fullmatch(r'/api/channels/(\d+)/messages',p)
   if m:
    ch=c.execute('SELECT * FROM channels WHERE id=?',(m.group(1),)).fetchone()
    if not ch:return err(self,404,'not found')
    body=d.get('body','')
    if not body:return err(self,400,'empty message')
    if body.startswith('/') and not body.startswith('//'):
     if body.startswith('/shrug'): body=body[6:].strip()+' ¯\\_(ツ)_/¯'
     elif body.startswith('/me '): pass
     elif body.startswith('/'): return err(self,400,'unknown command')
    c.execute('INSERT INTO seq(channel_id,n) VALUES(?,1) ON CONFLICT(channel_id) DO UPDATE SET n=n+1',(ch['id'],))
    ev=c.execute('SELECT n FROM seq WHERE channel_id=?',(ch['id'],)).fetchone()['n']; c.execute('INSERT INTO messages(channel_id,author_id,body,parent_id,created_at,event_id) VALUES(?,?,?,?,?,?)',(ch['id'],u['id'],body,d.get('parent_id'),now(),ev)); r=c.execute('SELECT * FROM messages WHERE id=?',(c.lastrowid,)).fetchone(); mo=msgobj(c,r)
    broadcast({'type':'message.reply' if r['parent_id'] else 'message.created','event_id':ev,'channel_id':ch['id'],'message':mo},ch['id']); return self.out(201,{'message':mo})
   m=re.fullmatch(r'/api/messages/(\d+)/reactions',p)
   if m:
    c.execute('INSERT OR IGNORE INTO reactions VALUES(?,?,?)',(m.group(1),u['id'],d.get('emoji',''))); rows=c.execute('SELECT emoji,COUNT(*) n,GROUP_CONCAT(user_id) ids FROM reactions WHERE message_id=? GROUP BY emoji',(m.group(1),)).fetchall(); return self.out(200,{'reactions':[{'emoji':x['emoji'],'count':x['n'],'user_ids':[int(z) for z in x['ids'].split(',')]} for x in rows]})
   m=re.fullmatch(r'/api/messages/(\d+)/pin',p)
   if m:
    c.execute('INSERT OR IGNORE INTO pins VALUES(?,?,?)',(m.group(1),u['id'],now())); r=c.execute('SELECT * FROM pins WHERE message_id=?',(m.group(1),)).fetchone(); return self.out(200,{'pin':dict(r)})
   m=re.fullmatch(r'/api/channels/(\d+)/(archive|unarchive)',p)
   if m:
    c.execute('UPDATE channels SET is_archived=? WHERE id=?',(1 if m.group(2)=='archive' else 0,m.group(1))); return self.out(200,{'channel':dict(c.execute('SELECT * FROM channels WHERE id=?',(m.group(1),)).fetchone())})
   m=re.fullmatch(r'/api/dms',p)
   if m:
    other=d.get('user_id'); ids=sorted([u['id'],other]); ch=c.execute('SELECT c.* FROM channels c JOIN cmembers a ON a.channel_id=c.id JOIN cmembers b ON b.channel_id=c.id WHERE c.is_dm=1 AND a.user_id=? AND b.user_id=?',(ids[0],ids[1])).fetchone()
    if not ch:
     c.execute('INSERT INTO channels(workspace_id,name,is_dm) VALUES(?,?,1)',(0,'dm-'+str(ids[0])+'-'+str(ids[1]))); cid=c.lastrowid
     for x in ids:c.execute('INSERT INTO cmembers VALUES(?,?)',(cid,x))
    else:cid=ch['id']
    return self.out(200,{'channel_id':cid})
  err(self,404,'not found')
 def do_PATCH(self):
  p=self.path.split('?')[0]; u=self.auth()
  if not u:return err(self,401,'authentication required')
  d=self.body()
  with db() as c:
   if p=='/api/users/me':
    if 'timezone' in d and ('/' not in d['timezone'] or d['timezone']=='Not/AZone'):return err(self,400,'invalid timezone')
    if any(len(str(v))>200 for v in d.values()):return err(self,400,'too long')
    allowed={'display_name','timezone','avatar_url','status_text','status_emoji'}
    for k,v in d.items():
     if k in allowed:c.execute('UPDATE users SET '+k+'=? WHERE id=?',(v,u['id']))
    r=c.execute('SELECT * FROM users WHERE id=?',(u['id'],)).fetchone(); broadcast({'type':'user.updated','user':objuser(r)}); return self.out(200,{'user':objuser(r)})
   m=re.fullmatch(r'/api/messages/(\d+)',p)
   if m:
    r=c.execute('SELECT * FROM messages WHERE id=?',(m.group(1),)).fetchone()
    if not r:return err(self,404,'not found')
    c.execute('UPDATE messages SET body=?,edited_at=? WHERE id=?',(d.get('body',''),now(),r['id'])); r=c.execute('SELECT * FROM messages WHERE id=?',(r['id'],)).fetchone(); return self.out(200,{'message':msgobj(c,r)})
  err(self,404,'not found')
 def do_DELETE(self):
  p=self.path; u=self.auth()
  if not u:return err(self,401,'authentication required')
  with db() as c:
   m=re.fullmatch(r'/api/messages/(\d+)',p)
   if m:c.execute('UPDATE messages SET deleted=1 WHERE id=?',(m.group(1),)); return self.out(200,{'deleted':True})
   m=re.fullmatch(r'/api/messages/(\d+)/reactions/(.+)',p)
   if m:c.execute('DELETE FROM reactions WHERE message_id=? AND user_id=? AND emoji=?',(m.group(1),u['id'],urllib.parse.unquote(m.group(2)))); return self.out(200,{'reactions':[]})
  err(self,404,'not found')
 def page(self):
  html='''<!doctype html><html><head><meta charset=utf-8><title>Huddle</title><style>body{font:16px Arial;margin:0;background:#f5f5f5;color:#222}button{border:0;padding:9px 14px;border-radius:4px;cursor:pointer}.primary{background:#007a5a;color:#fff}.danger{background:#e01e5a;color:#fff}.secondary{background:#1264a3;color:#fff}#app{padding:30px;max-width:1100px;margin:auto}input,textarea{padding:10px;margin:5px;border:1px solid #bbb;border-radius:4px}.layout{display:grid;grid-template-columns:240px 1fr;background:white;min-height:650px}.side{background:#3f0e40;color:white;padding:20px}.main{padding:25px}.msg{padding:12px;border-bottom:1px solid #eee}</style></head><body><div id=app><div id=auth-modal><h1>Huddle</h1><form data-testid=auth-form><input name=username placeholder=username required><input name=password type=password placeholder=password required><button data-testid=auth-submit data-button-role=primary class=primary>Sign in</button></form><p id=error></p></div><div id=chat hidden><div class=layout><aside class=side><h2 data-testid=workspace-header>Workspace</h2><div data-testid=current-user></div><button data-testid=new-channel-btn data-button-role=secondary class=secondary>New channel</button><button data-testid=logout-btn data-button-role=danger class=danger>Logout</button><div data-testid=channel-list></div></aside><main class=main><h2 data-testid=channel-title># general</h2><div data-testid=channel-topic></div><div data-testid=message-list></div><form id=send><input data-testid=message-input name=body><button data-testid=send-btn data-button-role=primary class=primary>Send</button></form></main></div></div></div><script>
const A='/api';let token=localStorage.getItem('huddle.token'),me,channels=[],cur;
async function api(u,o={}){o.headers={...(o.headers||{}),Authorization:'Bearer '+token,'Content-Type':'application/json'};let r=await fetch(A+u,o);return [r.status,await r.json().catch(()=>({}))]}
async function load(){let [s,x]=await api('/auth/me');if(s!=200)return;me=x.user;document.querySelector('#auth-modal').hidden=true;document.querySelector('#chat').hidden=false;document.querySelector('[data-testid=current-user]').textContent=me.display_name;let w=await api('/workspaces');if(w[1].workspaces.length){let z=await api('/workspaces/'+w[1].workspaces[0].slug);channels=z[1].channels;renderChannels();if(channels[0])select(channels[0])}}
function renderChannels(){let x=document.querySelector('[data-testid=channel-list');x.innerHTML=channels.map(c=>`<div data-testid=channel-entry data-channel-id=${c.id} data-channel-name=${c.name} onclick="select(channels.find(x=>x.id==${c.id}))"># ${c.name}</div>`).join('')}
async function select(c){cur=c;document.querySelector('[data-testid=channel-title]').textContent='# '+c.name;let x=await api('/channels/'+c.id+'/messages');document.querySelector('[data-testid=message-list]').innerHTML=x[1].messages.reverse().map(m=>`<div class=msg data-testid=message><b>${m.author.display_name}</b> <span data-testid=message-body>${m.body}</span></div>`).join('')}
document.querySelector('[data-testid=auth-form]').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));let x=await fetch(A+'/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}),j=await x.json();if(x.status==200){token=j.token;localStorage.setItem('huddle.token',token);load()}else document.querySelector('#error').textContent=j.error||'Invalid login'}
document.querySelector('#send').onsubmit=async e=>{e.preventDefault();let i=e.target.body;if(i.value.trim()&&cur){await api('/channels/'+cur.id+'/messages',{method:'POST',body:JSON.stringify({body:i.value})});i.value='';select(cur)}}
document.querySelector('[data-testid=logout-btn]').onclick=()=>{localStorage.removeItem('huddle.token');location.reload()};if(token)load();
</script></body></html>'''
  b=html.encode(); self.send_response(200);self.send_header('Content-Type','text/html');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b)
 def websocket(self,t):
  u=tokuser(t)
  if not u:return err(self,401,'invalid token')
  s=self.request; key=self.headers.get('Sec-WebSocket-Key',''); s.sendall(('HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: '+base64.b64encode(hashlib.sha1((key+'258EAFA5-E914-47DA-95CA-C5AB0DC85B11').encode()).digest()).decode()+'\r\n\r\n').encode()); clients.append((s,None,u['id']))
  try:
   while True:
    h=s.recv(2)
    if not h:break
    ln=h[1]&127
    if ln==126:ln=struct.unpack('>H',s.recv(2))[0]
    elif ln==127:ln=struct.unpack('>Q',s.recv(8))[0]
    mask=s.recv(4); data=s.recv(ln); data=bytes(data[i]^mask[i%4] for i in range(ln)); d=json.loads(data); 
    if d.get('type') in ('subscribe','resume'):
     for i,x in enumerate(clients):
      if x[0] is s: clients[i]=(s,d.get('channel_id'),u['id'])
     ws_send(s,json.dumps({'type':'subscribed' if d['type']=='subscribe' else 'resumed','channel_id':d.get('channel_id'),'head_event_id':0}))
  except: pass
  finally:
   for x in clients[:]:
    if x[0] is s:clients.remove(x)
def irc_line(x):return (x+'\r\n').encode()
def irc():
 srv=socket.socket();srv.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1);srv.bind(('0.0.0.0',6667));srv.listen()
 while True:
  s,_=srv.accept(); threading.Thread(target=irc_client,args=(s,),daemon=True).start()
def irc_client(s):
 nick='guest'; token=''; ch=None
